import { readFileSync } from "node:fs";
import { join } from "node:path";
import process from "node:process";
import { expect, plantDir, plantFile, test } from "@orb/testkit/tooling";
import { vi } from "vitest";
import type { Hit } from "../../../tooling/src/ui-facts/hand-model.ts";
import { byPlace } from "../../../tooling/src/ui-facts/hand-model.ts";
import { runUiFacts } from "../../../tooling/src/ui-facts/index.ts";

const THEME = [
  "/* GENERATED by tokens.build.ts from tokens.json - DO NOT EDIT. */",
  "@theme {",
  "  --spacing-row: round(up, 0.5rem, 1px);",
  "  --spacing-section: round(up, 1.5rem, 1px);",
  "  --container-cq-20: 20rem;",
  "  --border-width-control: 1px;",
  "  --opacity-receded: 60%;",
  "  --z-modal: 50;",
  "  --motion-fast: 130ms;",
  "  --color-primary: oklch(0.72 0.175 52);",
  "}",
  "",
].join("\n");
const UI_PACKAGE = JSON.stringify({
  exports: { "./layout": "./src/layout/index.ts", "./text": "./src/primitives/text/index.ts", "./button": "./src/primitives/button/index.ts" },
});
const LAYOUT_VARIANTS = 'export const stackVariants = tv({ variants: { gap: { row: "", field: "" }, align: { start: "", center: "" } } });';
const TEXT_VARIANTS = 'export const textVariants = tv({ variants: { lines: { one: "", two: "" }, tone: { muted: "" } } });';
const EXCEPTIONS = JSON.stringify({ entries: [] });
const FEATURE = "packages/client/src/features/probe";

function plant(root: string, files: Readonly<Record<string, string>>): void {
  plantFile(root, "tooling/src/ui-facts/exceptions.json", EXCEPTIONS);
  plantFile(root, "packages/ui/package.json", UI_PACKAGE);
  plantFile(root, "packages/ui/src/styles/theme.css", THEME);
  plantFile(root, "packages/ui/src/layout/variants.ts", LAYOUT_VARIANTS);
  plantFile(root, "packages/ui/src/primitives/text/variants.ts", TEXT_VARIANTS);
  for (const [path, text] of Object.entries(files)) {
    plantFile(root, `${FEATURE}/${path}`, text);
  }
}

/** The census through the CLI entry: `pnpm ui-facts --only=hand-rolling`, read back from the JSON it writes. */
function census(root: string, only = "hand-rolling"): { readonly hits: readonly Hit[]; readonly markdown: string } {
  const write = vi.spyOn(process.stdout, "write").mockImplementation(() => true);
  try {
    runUiFacts([`--root=${root}`, "--out=census", `--only=${only}`]);
  } finally {
    write.mockRestore();
  }
  const json = JSON.parse(readFileSync(join(root, "census/ui-facts.json"), "utf8")) as { readonly handRolling: readonly Hit[] };
  return { hits: json.handRolling, markdown: readFileSync(join(root, "census/ui-facts.md"), "utf8") };
}

const compare = (left: string, right: string): number => left.localeCompare(right);
const brief = (hit: Hit | undefined): readonly unknown[] => [hit?.category, hit?.verdict, hit?.owner];
const named = (hits: readonly Hit[], detail: string): Hit | undefined => hits.find((hit) => hit.detail === detail);

test("a sheet literal equal to a token is a token-literal naming it, and a structural value stays", ({ scratch }) => {
  const root = plantDir(scratch, "sheet-tokens");
  plant(root, {
    "styles/probe.css": [
      ".a {",
      "  transition-duration: 130ms;",
      "  z-index: 50;",
      "  opacity: 0.6;",
      "  padding-block: 24px;",
      "  border-width: 1px;",
      "  color: oklch(0.72 0.175 52);",
      "  background-color: oklch(from var(--surface) l c h / 0.4);",
      "}",
      "@container (min-width: 20rem) {",
      "  .a { margin: 0; inline-size: 100%; }",
      "}",
      ".b { transform: translateX(8px); }",
      "",
    ].join("\n"),
  });
  const { hits } = census(root);
  expect(brief(named(hits, "transition-duration: 130ms"))).toEqual(["token-literal", "token", "--motion-fast"]);
  expect(brief(named(hits, "z-index: 50"))).toEqual(["token-literal", "token", "--z-modal"]);
  expect(brief(named(hits, "opacity: 0.6"))).toEqual(["token-literal", "token", "--opacity-receded"]);
  expect(brief(named(hits, "padding-block: 24px"))).toEqual(["token-literal", "token", "--spacing-section"]);
  expect(brief(named(hits, "border-width: 1px"))).toEqual(["token-literal", "token", "--border-width-control"]);
  expect(brief(named(hits, "color: oklch(0.72 0.175 52)"))).toEqual(["token-literal", "token", "--color-primary"]);
  // A colour derived from a token is composition, so it stays.
  expect(named(hits, "background-color: oklch(from var(--surface) l c h/0.4)")?.keep).toBe("derived-colour");
  expect(brief(named(hits, "@container 20rem"))).toEqual(["token-literal", "token", "--container-cq-20"]);
  // Zero, a percentage and a transform are CSS structure: classified keep, each with its reason.
  expect([named(hits, "margin: 0")?.keep, named(hits, "inline-size: 100%")?.keep, named(hits, "transform: translateX(8px)")?.keep]).toEqual([
    "zero-sentinel",
    "relative-unit",
    "css-mechanism",
  ]);
});

test("a literal no token holds is a raw value asking for a new token, with the nearest token named", ({ scratch }) => {
  const root = plantDir(scratch, "raw-values");
  plant(root, {
    "styles/probe.css": ".a { padding-block: 18px; opacity: 0.5; }\n",
    "components/raw.ts": [
      'export const WIDTH = "20.5rem";',
      'export const PICK = "#abcdef";',
      'export const ANCHOR = "#review";',
      'export const NOTE = "wait 5 seconds";',
    ].join("\n"),
  });
  const { hits } = census(root);
  const padding = named(hits, "padding-block: 18px");
  expect(brief(padding)).toEqual(["raw-value", "token", "new token: length 18px"]);
  expect(padding?.reason).toContain("nearest is --spacing-section");
  expect(brief(named(hits, "opacity: 0.5"))).toEqual(["raw-value", "token", "new token: opacity 0.5"]);
  expect(brief(named(hits, '"20.5rem"'))).toEqual(["raw-value", "token", "new token: length 328px"]);
  expect(brief(named(hits, '"#abcdef"'))).toEqual(["raw-value", "token", "new token: colour #abcdef"]);
  // A URL fragment and a sentence are not values.
  expect(named(hits, '"#review"')).toBeUndefined();
  expect(named(hits, '"wait 5 seconds"')).toBeUndefined();
});

test("a class utility on a primitive that declares its axis is a recipe candidate, and a token-shaped utility with no owner stays quiet", ({ scratch }) => {
  const root = plantDir(scratch, "class-utilities");
  plant(root, {
    "components/uses.tsx": [
      'import { Stack } from "@orb/ui/layout";',
      'import { Text } from "@orb/ui/text";',
      "export const A = () => (",
      "  <>",
      '    <Stack className="gap-row items-center flex" />',
      '    <Text className="truncate">x</Text>',
      '    <Stack className="w-[18px] grid-cols-[minmax(0,1fr)_auto] opacity-100 py-px" />',
      "  </>",
      ");",
    ].join("\n"),
  });
  const { hits } = census(root);
  const classes = hits.filter((hit) => hit.category === "class-utility");
  expect(brief(named(classes, "gap-row"))).toEqual(["class-utility", "recipe", "layout.gap"]);
  expect(brief(named(classes, "items-center"))).toEqual(["class-utility", "recipe", "layout.align"]);
  expect(brief(named(classes, "truncate"))).toEqual(["class-utility", "recipe", "text.lines"]);
  expect(brief(named(classes, "w-[18px]"))).toEqual(["class-utility", "token", "new token: length 18px"]);
  // `flex` has no axis; a track formula, a visibility sentinel and the theme's px step are not hand-rolled values.
  expect(named(classes, "flex")).toBeUndefined();
  expect([named(classes, "grid-cols-[minmax(0,1fr)_auto]")?.keep, named(classes, "opacity-100")?.keep, named(classes, "py-px")?.keep]).toEqual([
    "css-mechanism",
    "zero-sentinel",
    "token-utility",
  ]);
});

test("a style prop carries a design value only when it writes a literal; a computed value is a runtime value", ({ scratch }) => {
  const root = plantDir(scratch, "styles");
  plant(root, {
    "components/styled.tsx": [
      'import { Stack } from "@orb/ui/layout";',
      "export const A = ({ measured, tone }: { measured: number; tone: string }) => (",
      "  <>",
      '    <Stack style={{ padding: "18px", zIndex: 50 }} />',
      "    <Stack style={{ width: measured, color: tone, inlineSize: measured * 2 }} />",
      '    <Stack style={{ paddingBlockStart: 0, "--probe-gap": measured }} />',
      "  </>",
      ");",
    ].join("\n"),
  });
  const styles = census(root).hits.filter((hit) => hit.category === "inline-style");
  expect(brief(named(styles, 'padding: "18px"'))).toEqual(["inline-style", "token", "new token: length 18px"]);
  expect(brief(named(styles, "zIndex: 50"))).toEqual(["inline-style", "token", "--z-modal"]);
  expect(
    styles
      .filter((hit) => hit.keep === "runtime-value")
      .map((hit) => hit.detail.split(":")[0] ?? "")
      .sort(compare),
  ).toEqual(['"--probe-gap"', "color", "inlineSize", "width"]);
  expect(named(styles, "paddingBlockStart: 0")?.keep).toBe("zero-sentinel");
});

test("a class set written three times is a repeated cluster, and twice is not", ({ scratch }) => {
  const root = plantDir(scratch, "clusters");
  const trio = 'className="flex-1 min-inline-0 truncate"';
  plant(root, {
    "components/a.tsx": `export const A = () => (<><span ${trio} /><span ${trio} /></>);`,
    "components/b.tsx": `export const B = () => <span ${trio} />;`,
    "components/c.tsx": 'export const C = () => (<><span className="rounded-lg border p-2" /><span className="rounded-lg border p-2" /></>);',
  });
  const clusters = census(root).hits.filter((hit) => hit.category === "repeated-cluster");
  expect(clusters).toHaveLength(3);
  expect(new Set(clusters.map((hit) => hit.owner))).toEqual(new Set(["composite TruncatingBox: flex-1 min-inline-0 truncate"]));
  expect(new Set(clusters.map((hit) => hit.verdict))).toEqual(new Set(["primitive"]));
});

test("a raw element a primitive owns is hand-built, and a plain wrapper is not", ({ scratch }) => {
  const root = plantDir(scratch, "hand-built");
  plant(root, {
    "components/raw.tsx": [
      "export const A = () => (",
      "  <>",
      '    <button type="button">go</button>',
      '    <div className="flex gap-row" />',
      '    <div className="rounded-lg border bg-card" />',
      '    <div style={{ display: "grid" }} />',
      '    <div className="shell-panel-edge"><div /></div>',
      "  </>",
      ");",
    ].join("\n"),
  });
  const built = census(root).hits.filter((hit) => hit.category === "hand-built");
  expect(built.map((hit) => `${hit.detail} -> ${hit.owner}`).sort(compare)).toEqual(
    [
      "<button> -> Button, GlyphButton or InlineAction (@orb/ui/button)",
      "<div className> -> Row (@orb/ui/layout)",
      "<div className> -> Card (@orb/ui/card)",
      'display: "grid" -> Stack, Row or Grid (@orb/ui/layout)',
    ].sort(compare),
  );
});

test("constants repeat one concept across files; an equal animation duration is a token, and one-off timers stay", ({ scratch }) => {
  const root = plantDir(scratch, "constants");
  plant(root, {
    "components/one.ts": "export const SEARCH_DEBOUNCE_MS = 250;",
    "components/two.ts": "export const CHARACTER_SEARCH_DEBOUNCE_MS = 250;",
    "components/three.ts": ["export const RETRY_MS = 3000;", "export const FADE_MS = 130;", "export const BACKLOG_PER_SEC = 90;"].join("\n"),
    "components/four.ts": "export const TICK_MS = 130;",
  });
  const { hits } = census(root);
  const debounce = hits.filter((hit) => hit.category === "repeated-constant");
  expect(debounce.map((hit) => [hit.verdict, hit.owner])).toEqual([
    ["decide", "constant: 250ms debounce"],
    ["decide", "constant: 250ms debounce"],
  ]);
  expect(brief(named(hits, "FADE_MS = 130ms"))).toEqual(["token-literal", "token", "--motion-fast"]);
  // A 130ms number named TICK is not an animation, and a one-off retry has nothing to repeat; a rate is not a duration.
  expect([named(hits, "TICK_MS = 130ms")?.keep, named(hits, "RETRY_MS = 3000ms")?.keep]).toEqual(["single-constant", "single-constant"]);
  expect(hits.some((hit) => hit.detail.startsWith("BACKLOG_PER_SEC"))).toBe(false);
});

test("the report is sorted and grouped by owner with counts per category and per surface, deterministically, and skips generated files", ({ scratch }) => {
  const root = plantDir(scratch, "report");
  plant(root, {
    "styles/probe.css": ".a { padding-block: 18px; z-index: 50; }\n",
    "components/uses.tsx": 'import { Stack } from "@orb/ui/layout";\nexport const A = () => <Stack className="gap-row" />;\n',
  });
  plantFile(
    root,
    "packages/ui/src/tokens/index.ts",
    '/** GENERATED by tokens.build.ts from tokens.json — DO NOT EDIT. */\nexport const COLOUR = "oklch(0.72 0.175 52)";\n',
  );
  const first = census(root);
  const second = census(root);
  expect(second.hits).toEqual(first.hits);
  expect(first.hits).toEqual(first.hits.toSorted(byPlace));
  expect(first.hits.some((hit) => hit.path.endsWith("tokens/index.ts"))).toBe(false);
  expect(first.markdown).toContain("### Hits per category");
  expect(first.markdown).toContain("| token-literal | 1 | 1 | 0 | 0 | 0 | 0 |");
  expect(first.markdown).toContain("| probe | 3 | 1 | 1 | 1 | 0 | 0 | 0 | 0 | 0 |");
  expect(first.markdown).toContain("#### layout.gap (1)");
  expect(first.markdown).not.toContain("## The split: bypass or gap");
});

test("--only names a section and the census part together: the census is scoped to the section", ({ scratch }) => {
  const root = plantDir(scratch, "scoped");
  plant(root, { "styles/probe.css": ".a { padding-block: 18px; }\n" });
  plantFile(root, "packages/client/src/features/other/styles/other.css", ".b { padding-block: 19px; }\n");
  const { hits, markdown } = census(root, "hand-rolling,probe");
  expect(hits.length).toBeGreaterThan(0);
  expect(markdown).toContain("padding-block: 18px");
  expect(markdown).not.toContain("padding-block: 19px");
});
